import urllib.request,re
html=urllib.request.urlopen("http://host.docker.internal:8300/").read().decode()
srcs=re.findall(r'(?:src|href)="([^"]+\.js)"',html)
print(srcs[:20])
for s in srcs:
    url=s if s.startswith('http') else 'http://host.docker.internal:8300'+s
    try:
        js=urllib.request.urlopen(url).read().decode()
    except Exception as e:
        print(e); continue
    for m in set(re.findall(r'[^"\'`]{0,80}experiments?[^"\'`]{0,80}',js)):
        if 'api' in m or 'complete' in m or 'end' in m or 'rollout' in m.lower():
            print(s, '|', m[:200])
EOF

